insert into PBC_REPORT_BALANCETERM (DETAILUUID, REPORTUUID, REPORTTYPE,
  GROUPTYPE, PROPERTYCODE, DEBT_INSTRUMENT,
  STOCK_RIGHT, SPECIAL_SHARE, ACTUAL_AMT
  )
values (#{detailuuid,jdbcType=CHAR}, #{reportuuid,jdbcType=CHAR}, #{reporttype,jdbcType=VARCHAR},
  #{grouptype,jdbcType=VARCHAR}, #{propertycode,jdbcType=VARCHAR}, #{debtInstrument,jdbcType=DECIMAL},
  #{stockRight,jdbcType=DECIMAL}, #{specialShare,jdbcType=DECIMAL}, #{actualAmt,jdbcType=DECIMAL}
  )

mapper.delete:
delete
from PBC_REPORT_BALANCETERM prp
where prp.REPORTUUID in(
select pr.REPORTUUID from PBC_REPORT pr
where 1=1

  and DATE_FORMAT(pr.STARTDATE,'%Y-%m-%d')>= #{reportStartDate,jdbcType=VARCHAR}


  and DATE_FORMAT(pr.ENDDATE,'%Y-%m-%d')>= #{reportEndDate,jdbcType=VARCHAR}


  and pr.REPORTTYPE = #{reporttype,jdbcType=VARCHAR}

and pr.send_status = '01'/*只删除未报送数据*/)
